INSERT INTO `users` (`id`, `name`, `email`, `password_hash`, `role`, `is_verified`, `profile_picture`, `remember_token`, `created_at`) VALUES (1,'Amara Osei','admin@travelvista.test','$2y$10$92/aIBt1W2MshTJG6F5SqeNPLp5OJdXYHxfD2GqVJF4Aas3ZTBIwG','admin',1,'avatar_admin.jpg',NULL,'2026-09-02 23:17:42'),(2,'Rina Haque','rina@travelvista.test','$2y$10$AQGiPtGnBbbt7tl7Y0QSD.y491a67tW.Aulliu3PwlUCpti8R7/n6','scout',1,'avatar_scout1.jpg',NULL,'2026-09-02 23:17:42'),(3,'Tomas Berg','tomas@travelvista.test','$2y$10$f2XrO.wY39PL3kuKIyHyWeDKjpzXOgV2HE4Seq85TqHF8tbuDITJi','scout',1,NULL,NULL,'2026-09-02 23:17:42'),(4,'Priya Nair','priya@travelvista.test','$2y$10$gUFIx.Omx7W3kutQ6k71X.eaVWzC.3.Kr0F4jOJ2M0V4378D3Z4M6','scout',0,NULL,NULL,'2026-09-02 23:17:42'),(5,'Jonah Whitfield','jonah@travelvista.test','$2y$10$92/aIBt1W2MshTJG6F5SqeNPLp5OJdXYHxfD2GqVJF4Aas3ZTBIwG','user',1,'avatars-a86b941922fed674-1788460501.jpg',NULL,'2026-09-02 23:17:42'),(6,'Leila Marchetti','leila@travelvista.test','$2y$10$PN.uMkgaxh8BlcSo/KgCT.OlwQ6U4zuHb59psvCGpeYVgYNhVcUhW','user',1,NULL,NULL,'2026-09-02 23:17:42'),(7,'Sam Okafor','sam@travelvista.test','$2y$10$9iXpa7WrNQldmUYsHOHWqu6Wcx6f6cCnrqFEcUIb8.gvQzNz9Vu2i','user',0,NULL,NULL,'2026-09-02 23:17:42');

-- posts
INSERT INTO `posts` (`id`, `scout_id`, `title`, `short_history`, `country`, `country_representation`, `genre`, `cost_level`, `travel_medium_info`, `image`, `status`, `created_at`, `updated_at`) VALUES ('1','2','Sigiriya, the rock that was a throne','In the fifth century a king who had taken his father\'s throne by force built a palace on top of a two-hundred-metre column of hardened magma. He ruled from it for eighteen years and then lost it in a single afternoon on the plain below.\n\nWhat is left is the climb: a staircase between the paws of a lion carved into the rock face, a gallery of frescoes halfway up that nobody has satisfactorily explained, and a mirror wall covered in graffiti left by visitors from the eighth century onward. The summit is a flat garden with the foundations of rooms still marked out in brick.\n\nGo at first light. By ten the stone is too hot to touch and the queue on the stairs stops moving.','Sri Lanka','Sri Lankans learn Sigiriya as the story of Kashyapa, the son who killed his father and was in turn deposed by his brother. It is taught less as an architectural triumph than as a parable about what ambition costs, which is a very Sri Lankan way of telling a story about a very impressive building.','historical','low','Flight to Colombo, then a four-hour bus or car to Dambulla','sigiriya.jpg','approved','2026-09-02 23:17:42','2026-09-03 19:12:01'),('2','2','The night market at Hoi An','Hoi An was a working port for four hundred years, trading with Japanese, Chinese, Dutch and Portuguese merchants, until the river silted up in the late 1800s and the trade moved to Da Nang. The town was left behind, which is exactly why it survived: nobody had a reason to knock anything down.\n\nThe night market runs along Nguyen Hoang street on the island side of the covered bridge. Silk lanterns, cao lau noodles made with water from one specific well, and boats selling paper lights to float downriver.\n\nThe old town charges an entry ticket that covers five heritage buildings. Buy it, and actually use all five.','Vietnam','Hoi An is the argument Vietnam makes about its own history: that it has always been a place other people passed through and left something behind, and that the result is not dilution but a particular kind of richness.','city','low','Flight to Da Nang, then a 45-minute taxi south','hoi_an.jpg','approved','2026-09-02 23:17:42','2026-09-03 19:12:01'),('3','3','Lofoten in the week the sun stops setting','These islands sit two hundred kilometres inside the Arctic Circle and should by rights be frozen solid. The Gulf Stream means they are not. Fishing villages have stood on the same rocks for a thousand years, drying cod on wooden frames exactly the way the Vikings did.\n\nFrom late May to mid July the sun does not go below the horizon. The light at one in the morning is the light of a long golden evening that refuses to end, and the mountains behind Reine turn the colour of wet copper.\n\nA hire car is not optional. Buses exist but they run to the fishing schedule, not yours.','Norway','Norwegians treat Lofoten as proof that the far north is not empty. The rorbuer - the red fishermen\'s cabins now rented to visitors - are a working argument that people have made a life up here for centuries and intend to keep doing it.','mountain','high','Flight to Bodo, ferry or short flight to Leknes, then a hire car','lofoten.jpg','approved','2026-09-02 23:17:42','2026-09-03 19:12:01'),('4','3','Wadi Rum by the light of the moon','Sandstone and granite pushed up out of the desert floor and then carved by wind for millions of years. T. E. Lawrence rode through here in 1917 and called it vast, echoing and god-like, which is overwritten but not wrong.\n\nYou cannot drive yourself into the protected area. You go with a Bedouin guide, which is the point: the families who run the camps have grazed these valleys for generations and know which canyon has the inscriptions and which one has the water.\n\nSleep in a camp, not a hotel in the village. The night sky here is the reason to come.','Jordan','Jordan sells Wadi Rum as cinema - Lawrence, Martian landscapes, film crews. The Bedouin who live there tell you about wells and grazing rights. Both are true and the gap between them is the most interesting thing about visiting.','desert','medium','Flight to Amman, four-hour drive south, then a Bedouin 4x4 into the protected area','wadi_rum.jpg','approved','2026-09-02 23:17:42','2026-09-03 19:12:01'),('5','2','Praia do Sancho, reached by ladder','Fernando de Noronha is a volcanic archipelago three hundred and fifty kilometres off the Brazilian coast. It has been a Portuguese fort, a prison, an American airbase and, since 1988, a national marine park with a hard cap on how many people may be on it at once.\r\n\r\nSancho is reached down a staircase bolted into a crack in the cliff, narrow enough that only one person can pass at a time. At the bottom is a crescent of sand that has been called the best beach in the world often enough to be embarrassing about it.\r\n\r\nThere is a daily environmental fee and it rises the longer you stay. Pay it without complaining; it is why the reef is still alive.','Brazil','Brazil is not short of coastline, so protecting Noronha this fiercely is a statement. The visitor cap and the fees are a national decision that some places are worth more intact than they are accessible.','beach','high','Flight to Recife or Natal, then a connecting flight to Fernando de Noronha','praia_do_sancho.jpg','approved','2026-09-02 23:17:42','2026-09-03 19:12:01'),('6','3','Ngorongoro, a crater full of animals','A volcano the size of a mountain collapsed in on itself two and a half million years ago and left a caldera twenty kilometres across with walls six hundred metres high. Grass grew on the floor, water collected, and animals walked in and largely stopped leaving.\n\nThe result is a density of wildlife that does not occur anywhere else: lion, elephant, hippo, flamingo, and one of the last populations of black rhino in the region, all inside a bowl you can see across.\n\nMaasai families still graze cattle inside the conservation area. Their presence is not a compromise on the park - it predates it.','Tanzania','Ngorongoro is Tanzania\'s most-argued-about landscape: a conservation area that is also grazing land that is also home. How the country resolves that says more about it than the animals do.','wildlife','high','Flight to Kilimanjaro, then a 4x4 through Karatu to the crater rim','ngorongoro.jpg','approved','2026-09-02 23:17:42','2026-09-03 19:12:01'),('7','2','The stone city of Zanzibar','Stone Town was built by Omani and Swahili merchants out of coral rag and mangrove poles, in streets deliberately too narrow for the sun to reach the ground. It was the centre of the East African spice and slave trade, and both facts are written into the same buildings.\n\nThe carved doors are the thing people photograph: brass-studded, some Indian in style, some Omani, dated by their brackets. The old slave market is now a cathedral, with the whipping post marked in the floor.\n\nGet lost on purpose. The town is small enough that you always come out somewhere.','Tanzania','Tanzania has not tidied Stone Town\'s history into something comfortable. The spice tours and the slave-trade memorial run out of the same square, and visitors are expected to hold both.','historical','medium','Flight or ferry from Dar es Salaam, then walk - cars barely fit','stone_town.jpg','approved','2026-09-02 23:17:42','2026-09-03 19:12:01'),('8','3','Faroe Islands: Sorvagsvatn above the sea','Eighteen volcanic islands in the North Atlantic, self-governing under Denmark, with more sheep than people and weather that changes every twenty minutes.\n\nSorvagsvatn is the largest lake in the Faroes, and it sits on a shelf about thirty metres above the ocean. Walk to the right vantage point and forced perspective makes it look as though the lake is hanging hundreds of metres in the air above the sea. It is an optical trick and it is still extraordinary in person.\n\nThe path is boggy and there is a small landowner\'s fee. Bring boots that you do not mind ruining.','Faroe Islands','The Faroese have spent decades arguing that a population of fifty thousand can run its own affairs. The tidy paths, the fee collected honestly at a hut, the tunnels under the sea - all of it is that argument, made in infrastructure.','island','medium','Flight to Vagar, then a 40-minute walk from the trailhead at Midvagur','sorvagsvatn.jpg','approved','2026-09-02 23:17:42','2026-09-03 19:12:01'),('17','3','Salar de Uyuni in the wet season','The largest salt flat on earth, ten thousand square kilometres of it, left behind when a prehistoric lake dried out. In the dry season it is a blinding white hexagonal crust. From December to April a few centimetres of water sit on top and the whole thing becomes a mirror.\n\nTours run from Uyuni town in 4x4 convoys. The three-day route south takes in the coloured lagoons and the geyser field at sunrise, at four thousand nine hundred metres.','Bolivia','Bolivia holds a very large share of the world lithium under that crust, and the country has spent twenty years arguing about who gets to extract it. The flat is beautiful and it is also a national economic question.','desert','medium','Flight to La Paz, then an overnight bus or a short flight to Uyuni','post_6a998a78aa743_uyuni.jpg','approved','2026-09-03 18:59:32','2026-09-03 20:55:52'),('18','4','Hampi, a capital left in the boulders','For two hundred years Hampi was the capital of the Vijayanagara empire and one of the largest cities in the world. In 1565 it was sacked over several months and never reoccupied. What is left is spread over twenty-six square kilometres of granite boulders: temples, a stone chariot, an aqueduct, the queen\'s bath.\n\nHire a bicycle. The site is far too large to walk and a rickshaw cannot reach half of it.','India','Hampi is the ruin Indians take their children to see, in the way other countries use battlefields: a demonstration that something enormous existed here and then did not.','historical','low','Train to Hospet from Bangalore or Goa, then a 30-minute auto-rickshaw','post_6a998a78aa749_hampi.jpg','approved','2026-09-03 19:05:58','2026-09-03 20:55:52'),('20','2','Cox\'s Bazar, the longest beach there is','One hundred and twenty kilometres of unbroken sand on the Bay of Bengal, usually called the longest natural sea beach in the world. The town behind it has grown from a fishing settlement into the country\'s busiest resort, and the difference between Laboni at the north end and Inani twenty kilometres south is the difference between a fairground and an empty coast.\n\nGo south. Hire a car for the Marine Drive and stop where nobody else has.','Bangladesh','Cox\'s Bazar is where Bangladesh takes its holidays. For a country with very little spare land, giving over a hundred kilometres of it to leisure is a statement about who the coast belongs to.','beach','low','Flight or overnight bus from Dhaka to Cox\'s Bazar, then a rickshaw to the shore','bd_20.jpg','approved','2026-09-09 17:37:33','2026-09-09 17:37:33'),('21','3','Saint Martin\'s Island, the only coral one','Bangladesh has exactly one coral island, eight square kilometres of it, sitting at the southernmost tip of the country. Locals call it Narikel Jinjira, coconut island. The reef around it is the only one in the country and it is in trouble from the boats that bring people to see it.\n\nThe ferry does not run in monsoon. Stay a night rather than doing the day trip - the island empties after four o\'clock and becomes a different place.','Bangladesh','Saint Martin\'s is the edge of the map for Bangladesh, and the argument over how many visitors it can carry each year is one the whole country follows.','island','medium','Bus or flight to Cox\'s Bazar, then the Teknaf ferry - November to March only','bd_21.jpg','approved','2026-09-09 17:37:33','2026-09-09 17:37:33'),('22','2','Kuakata, sunrise and sunset from one beach','Kuakata faces south into the bay on a spit of land narrow enough that you can watch the sun come up over the water and go down over it from the same stretch of sand. It is the only beach in the country where that is possible.\n\nThe name means well of water, after the wells the Rakhine community dug here in the eighteenth century. Their settlement and monastery are a few kilometres inland and worth the detour.','Bangladesh','Kuakata is called the daughter of the sea, and the Rakhine Buddhist community here is a reminder that the Bengal coast has never been one single culture.','beach','low','Bus from Dhaka to Kuakata, about eight hours now the Padma Bridge is open','bd_22.jpg','approved','2026-09-09 17:37:33','2026-09-09 17:37:33'),('23','3','Sonadia Island, before the developers','An uninhabited sandy island west of Cox\'s Bazar - nine square kilometres of dunes, mangrove scrub and salt flats. It matters far more than its size suggests: it is a critical stopover for migratory shorebirds, including the spoon-billed sandpiper, of which a few hundred remain on earth.\n\nThere is no accommodation and no electricity. Go with a local boatman, take water, and come back the same day.','Bangladesh','Sonadia is the test case for whether Bangladesh can leave somewhere alone. A deep-sea port was proposed here and shelved; the birds are still arriving in the meantime.','island','medium','Cox\'s Bazar to Ghatibhanga by road, then a small boat across the channel','bd_23.jpg','approved','2026-09-09 17:37:33','2026-09-09 17:37:33'),('24','2','Nijhum Dwip, an island of deer','A silent island - that is what the name means - in the Meghna estuary, formed by silt only in the 1950s. Someone released four deer here in the 1970s. There are now several thousand, moving through mangrove that was planted to hold the new land together.\n\nThe launch from Dhaka takes a night. Time the walk across the mudflats with the tide or you will wait several hours for it to go back out.','Bangladesh','Nijhum Dwip is land Bangladesh gained rather than lost, which in a delta losing ground to the sea is worth noticing.','island','medium','Dhaka to Hatiya by overnight launch, then a local boat and a walk across the flats','bd_24.jpg','approved','2026-09-09 17:37:33','2026-09-09 17:37:33'),('25','3','Sajek Valley, above the cloud line','Sajek sits at about eighteen hundred feet in Rangamati district, high enough that on most mornings the valley below fills with cloud and the ridges become islands. The road up is one of the best in the country and the last stretch runs along a ridge with drops on both sides.\n\nVehicles travel in escorted convoys at fixed times. Check the departure times before planning the day - miss one and you wait for the next.','Bangladesh','Sajek is in the Chittagong Hill Tracts, home to Lushai, Pankua and Tripura communities whose relationship with the Bangladeshi state has been complicated for fifty years. Arrive knowing that.','mountain','medium','Bus to Khagrachari, then a reserved jeep to Sajek in the escorted convoy','bd_25.jpg','approved','2026-09-09 17:37:33','2026-09-09 17:37:33'),('26','2','Bandarban, the hill district','The least densely populated district in Bangladesh and by far the most vertical. Bandarban holds the country\'s highest peaks - Saka Haphong, Keokradong, Tazing Dong - and eleven indigenous communities including the Marma, Mro, Bawm and Tripura.\n\nBandarban town is the base for most of the hill trips worth doing. Permits are needed for the deeper valleys and are arranged through the district office, so allow a day for paperwork.','Bangladesh','Bandarban is where the flat delta stops. For a country defined by rivers and rice, the hills are a genuinely different Bangladesh with different languages in them.','mountain','low','Bus from Dhaka or Chittagong to Bandarban town, then local jeeps into the hills','bd_26.jpg','approved','2026-09-09 17:37:33','2026-09-09 17:37:33'),('27','3','Nilgiri, the hill that keeps the clouds','Twenty-two hundred feet up the Chimbuk range, high enough that cloud moves through the cottages rather than below them. The army runs the resort at the top, which is why the road is as good as it is.\n\nThe Mro villages on the way up are not an attraction and should not be treated as one. Stop if you are invited, not otherwise.','Bangladesh','Nilgiri shows how much of the hill tracts is administered by the military. The comfort of the trip and the politics of the region are the same fact seen from two sides.','mountain','low','Bandarban town to Nilgiri by reserved jeep, about two hours of climbing road','bd_27.jpg','approved','2026-09-09 17:37:33','2026-09-09 17:37:33'),('28','2','Nilachal, the easy summit','Nilachal is the viewpoint you can reach in a quarter of an hour from Bandarban town, at around seventeen hundred feet with the Sangu valley laid out below. Early morning is the whole point: mist sits in the valley and burns off while you watch.\n\nGo at dawn or an hour before sunset. In the middle of the day it is hot, crowded, and the view is flat.','Bangladesh','Nilachal is the hill tracts made accessible to everyone, which is either a democratisation or a dilution depending on who you ask in Bandarban.','mountain','low','Fifteen minutes by rickshaw or jeep from Bandarban town','bd_28.jpg','approved','2026-09-09 17:37:33','2026-09-09 17:37:33'),('29','3','Boga Lake, a crater with no inlet','A natural lake at around eighteen hundred feet - fifteen acres of very deep, very clear water with no visible river feeding it. The Bawm villages around it have their own account of how it formed, involving a dragon; geologists suspect a volcanic or tectonic origin.\n\nThis is a two-day trip minimum from Bandarban and needs a permit and a registered guide. The final climb is steep and unshaded.','Bangladesh','Boga Lake is Bawm land, and the village beside it decides who stays and on what terms. Bangladesh has few places where that is so plainly true.','mountain','medium','Bandarban to Ruma by jeep and boat, then a steep climb on foot or by chander gari','bd_29.jpg','approved','2026-09-09 17:37:33','2026-09-09 17:37:33'),('30','2','The Sundarbans, where the tigers are','The largest mangrove forest on earth, ten thousand square kilometres split between Bangladesh and India, and the only mangrove forest anywhere that holds tigers. Around a hundred Royal Bengal tigers live in the Bangladeshi portion. You will almost certainly not see one.\n\nWhat you will see is the forest itself: sundari trees, spotted deer, crocodiles, kingfishers, and the honey collectors who go in each spring knowing the odds.\n\nGo on a licensed boat. Independent entry is not permitted.','Bangladesh','The Sundarbans is the country\'s storm barrier as much as its wilderness - it takes the first hit from every cyclone coming up the bay. Protecting it is flood policy, not only conservation.','wildlife','medium','Launch from Khulna or Mongla - a three-day live-aboard is the usual way','bd_30.jpg','approved','2026-09-09 17:37:33','2026-09-09 17:37:33'),('31','3','Ratargul, the forest that floods','One of very few freshwater swamp forests in the world and the only one in Bangladesh. For half the year it is ordinary woodland. Through the monsoon it stands in twenty to thirty feet of water and you row between the canopies.\n\nGo between July and September or there is nothing to row through. Insist on a rowed boat rather than an engine - the noise empties the forest of everything worth coming for.','Bangladesh','Ratargul only works because of the monsoon, the same flood the rest of the country spends all year preparing for. Here it is the attraction.','wildlife','low','Sylhet to Ratargul by CNG, then a rowed boat in among the trees','bd_31.jpg','approved','2026-09-09 17:37:33','2026-09-09 17:37:33'),('32','2','Lawachara, listening for gibbons','A patch of semi-evergreen rainforest in Moulvibazar and one of the last homes of the western hoolock gibbon - fewer than a hundred remain here. You hear them long before you see them; the call carries over a kilometre through the trees.\n\nGo at first light with a forest department guide. By nine the gibbons have stopped calling and the day-trippers have arrived.','Bangladesh','Lawachara is what is left of forest that once ran across the whole northeast. It is small enough to walk across in an afternoon, which is the point being made.','wildlife','low','Train from Dhaka to Srimangal, then twenty minutes by CNG','bd_32.jpg','approved','2026-09-09 17:37:33','2026-09-09 17:37:33'),('33','3','Bichanakandi, where the hills arrive','A stone-strewn riverbed at the point where water comes down out of the Meghalaya hills and spreads across the Bangladeshi plain. The Khasi hills stand directly behind, waterfalls visible on them in the wet season, and the river runs over boulders in clear channels.\n\nAlso spelled Bisnakandi. Come in monsoon when there is water; in the dry season it is a quarry with lorries in it.','Bangladesh','Bichanakandi is where Bangladesh ends and you can watch it happen - the border runs along the foot of those hills, and the stones in the river came from the other side.','mountain','low','Sylhet to Hadarpar by CNG, then a boat up the riverbed','bd_33.jpg','approved','2026-09-09 17:37:33','2026-09-09 17:37:33'),('34','2','Jaflong, the river off the border','The Piyain river comes out of India here carrying stones, and the stones are the local economy: boats, barges and thousands of workers pulling them out of the bed by hand. Between the extraction there is genuinely fine scenery, with the Dawki bridge visible on the Indian side.\n\nGo early, and go upstream past the collection points to where the water is still clear.','Bangladesh','Jaflong is a working landscape rather than a preserved one. It shows Bangladesh doing what it has always done with a river - taking what comes down it and putting it to use.','mountain','low','Sylhet to Jaflong by bus or CNG, about two hours','bd_34.jpg','approved','2026-09-09 17:37:33','2026-09-09 17:37:33'),('35','3','Madhabkunda, the drop and the pilgrims','Around two hundred feet of water coming off a rock face in Moulvibazar, one of the largest falls in the country and among the most visited. The pool at the base is popular; the rocks around it are slick and people are hurt here every year.\n\nThere is a Manipuri community nearby and a small tea estate on the approach road, both worth an hour if you have one.','Bangladesh','Madhabkunda draws Hindu pilgrims as well as tourists, and the shrine at the site is a reminder that Bangladesh\'s religious geography is older and more layered than it is usually described.','mountain','low','Train or bus to Kulaura, then a short road trip to the falls','bd_35.jpg','approved','2026-09-09 17:37:33','2026-09-09 17:37:33'),('36','2','Hum Hum, found in 2010','A waterfall in the Razkandi reserve that outsiders did not document until 2010, despite being about a hundred and fifty feet high. The local Tripura community knew about it; nobody had written it down.\n\nThe trek is through leech country in the wet season and involves stream crossings. Take a guide from the village - the path is not obvious and people do get lost on it.','Bangladesh','Hum Hum is a useful correction to the idea that a place is discovered when a city person arrives. It was known. It just was not on anyone\'s list.','mountain','low','Srimangal to Kalapur, then a guided trek of two to three hours each way','bd_36.jpg','approved','2026-09-09 17:37:33','2026-09-09 17:37:33'),('37','3','Amiakhum, the hardest one to reach','Widely called the most beautiful waterfall in Bangladesh, and it takes three days to stand in front of it. The route runs through Thanchi, Remakri, Nafakhum and Thuisapara, over ridges and along riverbeds, sleeping in Marma and Tripura villages.\n\nPermits, a registered guide and reasonable fitness are all mandatory. Do not attempt it in heavy monsoon; the river crossings turn lethal.','Bangladesh','Amiakhum is remote enough that reaching it depends entirely on the hill communities who host you along the way. There is no version of this trip that does not run through their villages.','mountain','medium','Bandarban to Thanchi by jeep, boat up the Sangu, then two days on foot','bd_37.jpg','approved','2026-09-09 17:37:33','2026-09-09 17:37:33'),('38','2','Nafakhum, the river falling sideways','Not the tallest fall in Bangladesh but the heaviest - the whole Remakri river goes over a ledge about thirty feet wide. In monsoon the noise arrives well before the view does.\n\nMost people reach it as part of the Amiakhum route, but it works as a shorter trip on its own from Remakri. The same permit rules apply.','Bangladesh','Nafakhum is on the Sangu, the only river in Bangladesh that rises inside the country rather than flowing in from India - a small point of independence in a nation of borrowed water.','mountain','medium','Bandarban to Thanchi, boat to Remakri, then about two hours on foot','bd_38.jpg','approved','2026-09-09 17:37:33','2026-09-09 17:37:33'),('39','3','Khadimnagar, an hour from the city','A small national park on the edge of Sylhet, under seven hundred hectares, with walking trails, a watchtower and enough tree cover to hold birds, macaques and the occasional jungle cat.\n\nIt is close enough to the city to do in a morning, which is its real value - most protected forest in Bangladesh takes a day to reach.','Bangladesh','Khadimnagar is proof that a Bangladeshi city can keep forest at its edge rather than pushing it out. Sylhet is one of the few that has managed it.','wildlife','low','Twenty minutes by CNG from Sylhet city','bd_39.jpg','approved','2026-09-09 17:37:33','2026-09-09 17:37:33'),('40','2','Somapura Mahavihara, the great monastery','The largest Buddhist monastery south of the Himalayas, built in the eighth century by the Pala king Dharmapala. Twenty-one acres, a hundred and seventy-seven monks\' cells around a central shrine that once stood over seventy feet. A UNESCO World Heritage site since 1985.\n\nThe site museum holds the terracotta plaques taken off the walls. See it before you walk the ruins, not after.','Bangladesh','Somapura is physical evidence that Bengal was a Buddhist centre for centuries before it was anything else - a fact the region\'s later history tends to bury.','historical','low','Train to Joypurhat or Santahar, then by road to Paharpur','bd_40.jpg','approved','2026-09-09 17:37:33','2026-09-09 17:37:33'),('41','3','Lalbagh Fort, never finished','A Mughal fort begun in 1678 by Prince Muhammad Azam and abandoned when his successor\'s daughter Pari Bibi died on the site. Her tomb sits at the centre of a complex that was never completed - a mosque, a hammam, a great gate, and nothing joining them.\n\nIt is in Old Dhaka, so combine it with Ahsan Manzil and the river. Closed Sundays and Monday mornings.','Bangladesh','Lalbagh is the Mughal empire stopping mid-sentence in Bengal. Dhaka has grown around and over it, which is arguably the more Bangladeshi story.','historical','low','Anywhere in Old Dhaka by rickshaw; it sits in the middle of the city','bd_41.jpg','approved','2026-09-09 17:37:33','2026-09-09 17:37:33'),('42','2','Ahsan Manzil, the pink palace','The residence of the Nawabs of Dhaka, built in the 1870s on the bank of the Buriganga and painted the pink it is still known for. The Muslim League was founded in a room here in 1906, which puts this building at the start of a chain of events ending in two partitions.\n\nThe river frontage is the best view of it. Take a boat across and look back.','Bangladesh','Ahsan Manzil is where modern South Asian politics began, in a drawing room, and Bangladesh keeps it in good repair for exactly that reason.','historical','low','On the Buriganga riverfront in Old Dhaka, best reached by rickshaw','bd_42.jpg','approved','2026-09-09 17:37:33','2026-09-09 17:37:33'),('43','3','Mahasthangarh, the oldest city','The earliest urban site found in Bangladesh - Pundranagara, capital of the Pundra kingdom, occupied from the third century BC. The citadel walls still stand five metres above the surrounding fields, and the site has been inhabited in some form for over two thousand years.\n\nThe museum is small but holds the Brahmi inscription that dated the place. Go there first.','Bangladesh','Mahasthangarh pushes Bengali urban history back two and a half millennia, which matters in a country often described as young.','historical','low','Train or bus to Bogura, then a short road trip north','bd_43.jpg','approved','2026-09-09 17:37:33','2026-09-09 17:37:33'),('44','2','Kantajew Temple, every inch covered','A late-Mughal-period Hindu temple finished in 1752, built entirely of brick and faced with terracotta plaques on every external surface - some fifteen thousand of them, showing scenes from the Ramayana, the Mahabharata and ordinary eighteenth-century Bengali life.\n\nIt lost its nine spires in the 1897 earthquake and they were never rebuilt. Go close; the detail is the reason to come.','Bangladesh','Kantajew is the high point of Bengali terracotta work, a craft that developed here precisely because the delta has clay and no stone.','historical','low','Bus or train to Dinajpur, then about twenty kilometres by road','bd_44.jpg','approved','2026-09-09 17:37:33','2026-09-09 17:37:33'),('45','3','Srimangal, the tea capital','The centre of Bangladeshi tea, with estates running to the horizon in every direction and the Lawachara forest, Baikka Beel wetland and several Manipuri and Khasi villages within an hour.\n\nAsk for the seven-layer tea in town - it is a genuine local invention, not a tourist trick, and nobody outside Srimangal has reproduced it properly.','Bangladesh','Tea is Bangladesh\'s oldest export industry and Srimangal is its centre, labour history included: the estate workers here descend from communities brought in under the British and are still fighting over wages.','mountain','low','Train from Dhaka to Srimangal, about six hours and the best way to arrive','bd_45.jpg','approved','2026-09-09 17:37:33','2026-09-09 17:37:33'),('46','2','Madhabpur Lake, inside the estate','A lake set inside a working tea estate in Kamalganj, with hills of tea rising straight out of the water on three sides. Blue lotus covers parts of it in season and the birdlife is good early.\n\nIt is on private estate land. Behave accordingly and do not wander into the picking areas.','Bangladesh','Madhabpur shows what a tea estate actually is - not scenery but a company town, with housing, a workforce, and a lake that happens to be beautiful.','mountain','low','From Srimangal by CNG, about forty minutes through the tea gardens','bd_46.jpg','approved','2026-09-09 17:37:33','2026-09-09 17:37:33'),('47','3','Tanguar Haor, a wetland that becomes a sea','A hundred square kilometres of wetland in Sunamganj that swells through the monsoon until the villages on it look like anchored boats. A Ramsar site, and one of the most important wintering grounds for migratory waterfowl in South Asia - over two hundred bird species.\n\nSleep on the boat. The point of the place is being on the water at dawn, and no hotel gives you that.','Bangladesh','Tanguar Haor is the haor basin at its most extreme, where the annual flood is not a disaster but the entire basis of how people live and fish.','wildlife','low','Sylhet or Sunamganj to Tahirpur, then a houseboat for one or two nights','bd_47.jpg','approved','2026-09-09 17:37:33','2026-09-09 17:37:33'),('48','2','Lalakhal, the green river','The Sari river comes down out of the Jaintia hills here and the water is a striking blue-green, a colour that comes from minerals carried off the hills upstream. Tea estates run down to the bank and the far side is India.\n\nThe colour is strongest in the dry season, roughly November to March. In monsoon the river is brown like every other river in the country.','Bangladesh','Lalakhal is the border as a river rather than a line, and the tea gardens on the Bangladeshi bank were laid out by the same colonial companies that planted the hills opposite.','mountain','low','Sylhet to Jaintiapur by road, then a boat up the Sari river','bd_48.jpg','approved','2026-09-09 17:37:33','2026-09-09 17:37:33');

