INSERT INTO `post_requests` (`id`, `scout_id`, `original_post_id`, `post_data`, `admin_note`, `requested_at`, `status`) VALUES (1,2,NULL,'{\"title\":\"Meteora, monasteries on the rock pillars\",\"country\":\"Greece\",\"genre\":\"historical\",\"cost_level\":\"medium\",\"base_cost\":\"1180\",\"travel_medium_info\":\"Train from Athens to Kalambaka, about five hours, then walk or take the local bus\",\"short_history\":\"Sandstone pillars rise three hundred metres straight out of the Thessalian plain, and monks started climbing them in the fourteenth century to get away from Ottoman raids. Six monasteries are still in use. For centuries the only way up was a rope and a net.\\n\\nStairs were cut into the rock in the 1920s. Take the bus to Kastraki and walk between them - the path between Varlaam and Great Meteoron is the best hour of the trip.\",\"country_representation\":\"Meteora is where Greek Orthodoxy becomes geography. The monasteries are working communities, not exhibits, and the dress code at the door is a reminder of that.\",\"image\":\"\"}',NULL,'2026-09-02 23:17:42','rejected'),(2,3,NULL,'{\"title\":\"Salar de Uyuni in the wet season\",\"country\":\"Bolivia\",\"genre\":\"desert\",\"cost_level\":\"medium\",\"base_cost\":\"1350\",\"travel_medium_info\":\"Flight to La Paz, then an overnight bus or a short flight to Uyuni\",\"short_history\":\"The largest salt flat on earth, ten thousand square kilometres of it, left behind when a prehistoric lake dried out. In the dry season it is a blinding white hexagonal crust. From December to April a few centimetres of water sit on top and the whole thing becomes a mirror.\\n\\nTours run from Uyuni town in 4x4 convoys. The three-day route south takes in the coloured lagoons and the geyser field at sunrise, at four thousand nine hundred metres.\",\"country_representation\":\"Bolivia holds a very large share of the world lithium under that crust, and the country has spent twenty years arguing about who gets to extract it. The flat is beautiful and it is also a national economic question.\",\"image\":\"\"}',NULL,'2026-09-02 23:17:42','approved'),(3,4,NULL,'{\"title\":\"Hampi, a capital left in the boulders\",\"country\":\"India\",\"genre\":\"historical\",\"cost_level\":\"low\",\"base_cost\":\"480\",\"travel_medium_info\":\"Train to Hospet from Bangalore or Goa, then a 30-minute auto-rickshaw\",\"short_history\":\"For two hundred years Hampi was the capital of the Vijayanagara empire and one of the largest cities in the world. In 1565 it was sacked over several months and never reoccupied. What is left is spread over twenty-six square kilometres of granite boulders: temples, a stone chariot, an aqueduct, the queen\'s bath.\\n\\nHire a bicycle. The site is far too large to walk and a rickshaw cannot reach half of it.\",\"country_representation\":\"Hampi is the ruin Indians take their children to see, in the way other countries use battlefields: a demonstration that something enormous existed here and then did not.\",\"image\":\"\"}',NULL,'2026-09-02 23:17:42','approved'),(5,4,NULL,'{\"title\":\"That beach I went to once\",\"country\":\"Thailand\",\"genre\":\"beach\",\"cost_level\":\"low\",\"base_cost\":\"\",\"travel_medium_info\":\"plane\",\"short_history\":\"It was really nice and the water was warm. There were some rocks. I would go again if I had the chance, probably in summer.\",\"country_representation\":\"\",\"image\":\"\"}','Needs the actual name of the beach and enough history for a reader to place it.','2026-09-02 23:17:42','rejected'),(6,2,5,'{\"title\":\"Praia do Sancho, reached by ladder\",\"country\":\"Brazil\",\"genre\":\"beach\",\"cost_level\":\"high\",\"base_cost\":\"\",\"travel_medium_info\":\"Flight to Recife or Natal, then a connecting flight to Fernando de Noronha\",\"short_history\":\"Fernando de Noronha is a volcanic archipelago three hundred and fifty kilometres off the Brazilian coast. It has been a Portuguese fort, a prison, an American airbase and, since 1988, a national marine park with a hard cap on how many people may be on it at once.\\r\\n\\r\\nSancho is reached down a staircase bolted into a crack in the cliff, narrow enough that only one person can pass at a time. At the bottom is a crescent of sand that has been called the best beach in the world often enough to be embarrassing about it.\\r\\n\\r\\nThere is a daily environmental fee and it rises the longer you stay. Pay it without complaining; it is why the reef is still alive.\",\"country_representation\":\"Brazil is not short of coastline, so protecting Noronha this fiercely is a statement. The visitor cap and the fees are a national decision that some places are worth more intact than they are accessible.\",\"image\":\"\"}',NULL,'2026-09-03 18:55:57','approved');
